INSERT INTO `HangHoa` (`maHangHoa`, `tenHangHoa`, `loaiHangHoa`, `donViTinhChuan`, `heSoQuyDoi`, `moTa`, `dieuKienBaoQuan`, `hanSuDungTieuChuanNgay`, `trangThai`) VALUES
  ('HH01000001', 'Ngô hạt vàng', 'Nguyên liệu', 'kg', 1, 'Ngô vàng nguyên hạt dùng phối trộn thức ăn chăn nuôi, độ ẩm tiêu chuẩn <= 14%', 'Silo hoặc kho khô ráo, thông thoáng, chống ẩm mốc', 180, 'Đang kinh doanh'),
  ('HH01000002', 'Cám gạo', 'Nguyên liệu', 'kg', 1, 'Cám gạo giàu chất xơ, vitamin và khoáng chất, độ ẩm <= 12%', 'Để nơi khô ráo, tránh ánh nắng trực tiếp và độ ẩm cao', 120, 'Đang kinh doanh'),
  ('HH01000003', 'Tấm gạo', 'Nguyên liệu', 'kg', 1, 'Tấm gạo sạch nguồn tinh bột dễ tiêu hóa cho gia súc, gia cầm', 'Khô thoáng, kiểm soát côn trùng định kỳ', 180, 'Đang kinh doanh'),
  ('HH01000004', 'Bột mì', 'Nguyên liệu', 'kg', 1, 'Bột mì công nghiệp cung cấp năng lượng và tăng độ kết dính viên thức ăn', 'Khô mát, nhiệt độ dưới 30°C, tránh ẩm ướt', 180, 'Đang kinh doanh'),
  ('HH01000005', 'Sắn lát khô', 'Nguyên liệu', 'kg', 1, 'Sắn lát phơi sấy khô giàu tinh bột, cung cấp năng lượng thô', 'Kho thông gió tự nhiên, chống ẩm mốc', 180, 'Đang kinh doanh'),
  ('HH01000006', 'Bột sắn', 'Nguyên liệu', 'kg', 1, 'Bột củ sắn nghiền mịn dùng làm chất kết dính và tạo năng lượng', 'Bảo quản nơi khô ráo, tránh ánh nắng và ẩm ướt', 180, 'Đang kinh doanh'),
  ('HH01000007', 'Khô đậu tương', 'Nguyên liệu', 'kg', 1, 'Khô dầu đậu tương ép trích ly giàu protein thực vật, độ đạm >= 46%', 'Kho thoáng khí, để trên pallet cách mặt sàn tối thiểu 15cm', 180, 'Đang kinh doanh'),
  ('HH01000008', 'Khô cải dầu', 'Nguyên liệu', 'kg', 1, 'Bã hạt cải dầu sau trích ly giàu protein và khoáng chất, đạm 36-38%', 'Kho râm mát, khô ráo, thông gió tốt', 180, 'Đang kinh doanh'),
  ('HH01000009', 'Khô hướng dương', 'Nguyên liệu', 'kg', 1, 'Bã khô hạt hướng dương bổ sung đạm và chất xơ tiêu hóa cho gia súc', 'Nơi khô thoáng, chống ẩm mốc và côn trùng', 180, 'Đang kinh doanh'),
  ('HH01000010', 'Bột cá', 'Nguyên liệu', 'kg', 1, 'Bột cá biển sấy khô giàu protein và axit amin thiết yếu, độ đạm >= 60%', 'Kho mát 20-25°C, kín gió, tránh nắng trực tiếp', 120, 'Đang kinh doanh'),
  ('HH01000011', 'Bột thịt xương', 'Nguyên liệu', 'kg', 1, 'Bột đạm động vật bổ sung canxi, phospho và protein, đạm >= 50%', 'Kho khô ráo, thoáng khí, kiểm soát động vật hại', 120, 'Đang kinh doanh'),
  ('HH01000012', 'Bột phụ phẩm gia cầm', 'Nguyên liệu', 'kg', 1, 'Bột chế biến từ phụ phẩm gia cầm giàu đạm và năng lượng, đạm >= 60%', 'Kho mát, che chắn kỹ, tránh ẩm mốc', 120, 'Đang kinh doanh'),
  ('HH01000013', 'Dầu đậu nành', 'Nguyên liệu', 'kg', 1, 'Dầu thực vật thô từ hạt đậu nành bổ sung lipid và năng lượng', 'Bồn chuyên dụng hoặc phuy kín, tránh ánh nắng và oxy hóa', 240, 'Đang kinh doanh'),
  ('HH01000014', 'Dầu cọ', 'Nguyên liệu', 'kg', 1, 'Dầu cọ thô giàu axit béo bổ sung năng lượng cao trong khẩu phần', 'Bồn ủ ấm chuyên dụng hoặc phuy kín, nhiệt độ thích hợp', 240, 'Đang kinh doanh'),
  ('HH01000015', 'Tinh bột bắp', 'Nguyên liệu', 'kg', 1, 'Tinh bột bắp tinh khiết cung cấp năng lượng tiêu hóa nhanh', 'Kho khô ráo, kê pallet, chống ẩm mốc', 365, 'Đang kinh doanh'),
  ('HH01000016', 'Bột đá vôi', 'Nguyên liệu', 'kg', 1, 'Canxi cacbonat tự nhiên nghiền mịn bổ sung canxi cho vật nuôi', 'Nơi khô ráo, kê cao trên pallet, tránh dột nước', 730, 'Đang kinh doanh'),
