  ('HH03000013', 'Hỗn hợp trước ép viên', 'Bán thành phẩm', 'kg', 1, 'Bột sau tiền điều nhiệt áp suất hơi nạp đầu ép đùn extruder thuộc dây chuyền thức ăn thủy sản', 'Phễu cấp liệu liên tục đầu máy ép đùn', 7, 'Đang kinh doanh'),
  ('HH03000014', 'Thức ăn viên sau ép', 'Bán thành phẩm', 'kg', 1, 'Viên cám sau công nghệ ép đùn giãn nở cắt khuôn tốc độ cao thuộc dây chuyền thức ăn thủy sản', 'Hệ thống vận chuyển khí động học sang buồng sấy', 7, 'Đang kinh doanh'),
  ('HH03000015', 'Thức ăn viên sau sấy', 'Bán thành phẩm', 'kg', 1, 'Viên cám sau hệ thống sấy tầng sôi đa tầng kiểm soát độ ẩm thuộc dây chuyền thức ăn thủy sản', 'Băng tải dẫn sang máy phủ áo chân không', 7, 'Đang kinh doanh'),
  ('HH03000016', 'Hỗn hợp sau trộn vi lượng', 'Bán thành phẩm', 'kg', 1, 'Hỗn hợp phụ gia, khoáng, enzyme bổ sung chuyên biệt thuộc dây chuyền thức ăn thủy sản', 'Thùng chứa chuyên dụng phòng pha chế vi lượng', 30, 'Đang kinh doanh'),
  ('HH03000017', 'Thức ăn viên sau làm nguội', 'Bán thành phẩm', 'kg', 1, 'Viên cám sau tháp làm mát ngược chiều ổn định cấu trúc viên thuộc dây chuyền thức ăn thủy sản', 'Phễu trung gian trước công đoạn phủ màng bọc', 15, 'Đang kinh doanh'),
  ('HH03000018', 'Thức ăn viên sau phủ áo', 'Bán thành phẩm', 'kg', 1, 'Viên thức ăn sau công nghệ phủ áo chân không dầu cá và chất dẫn dụ thuộc dây chuyền thủy sản', 'Silo chờ đóng gói bao bì thành phẩm', 15, 'Đang kinh doanh'),
  ('HH04000001', 'Bao PP dệt 25 kg', 'Bao bì', 'kg', 0.12, 'Vỏ bao PP dệt tải trọng 25 kg dùng đóng gói thức ăn gia súc gia cầm (vỏ ~0.12 kg/bao)', 'Kê pallet gọn gàng, tránh ánh nắng và nguồn nhiệt', NULL, 'Đang kinh doanh'),
  ('HH04000002', 'Bao PP dệt 40 kg', 'Bao bì', 'kg', 0.65, 'Vỏ bao PP dệt chịu tải 40 kg đóng gói cám bò và cá tra (định mức ~0.65 kg/đơn vị)', 'Khô ráo, che chắn bụi bẩn và tia UV', NULL, 'Đang kinh doanh'),
  ('HH04000003', 'Bao BOPP in màng', 'Bao bì', 'kg', 0.15, 'Vỏ bao màng phức hợp BOPP in ống đồng cao cấp chống ẩm (vỏ ~0.15 kg/bao)', 'Nơi khô ráo, tránh vật sắc nhọn và đè nén quá tải', NULL, 'Đang kinh doanh'),
  ('HH04000004', 'Bao jumbo', 'Bao bì', 'kg', 2.5, 'Bao Jumbo FIBC 4 quai nâng miệng nạp đáy xả tải trọng 1000 kg (vỏ ~2.50 kg/bao)', 'Xếp ngay ngắn trên kệ, tránh dính dầu mỡ hóa chất', NULL, 'Đang kinh doanh'),
  ('HH04000005', 'Bao PE lót trong', 'Bao bì', 'kg', 0.05, 'Túi nilon PE dẻo dùng lót trong bao 25 kg ngăn ẩm và chống bay mùi (vỏ ~0.05 kg/bao)', 'Bọc kín, tránh bụi bẩn và nơi có nhiệt độ cao', NULL, 'Đang kinh doanh'),
  ('HH04000006', 'Bao ghép màng nhiều lớp', 'Bao bì', 'kg', 0.2, 'Bao phức hợp màng nhôm giấy nhiều lớp bảo quản premix và phụ gia (vỏ ~0.20 kg/bao)', 'Khô ráo tuyệt đối, kê trên pallet nhựa', NULL, 'Đang kinh doanh'),
  ('HH04000007', 'Thùng carton 5 lớp nhỏ', 'Bao bì', 'kg', 0.4, 'Thùng carton 5 lớp sóng BC cỡ nhỏ đóng gói hộp phụ gia (vỏ ~0.40 kg/thùng)', 'Kho khô ráo, che chắn chống ẩm và dột nước', NULL, 'Đang kinh doanh'),
  ('HH04000008', 'Thùng carton 5 lớp vừa', 'Bao bì', 'kg', 0.65, 'Thùng carton 5 lớp sóng cỡ trung đựng chai lọ premix vi lượng (vỏ ~0.65 kg/thùng)', 'Kho thoáng mát, xếp không quá 5 lớp thùng', NULL, 'Đang kinh doanh'),
  ('HH04000009', 'Thùng carton 5 lớp lớn', 'Bao bì', 'kg', 0.9, 'Thùng carton 5 lớp cỡ lớn chịu lực cao dùng đóng gói tổng hợp (vỏ ~0.90 kg/thùng)', 'Nơi cao ráo, cách sàn 15cm, PCCC nghiêm ngặt', NULL, 'Đang kinh doanh'),
  ('HH04000010', 'Bao PP dệt 10 kg', 'Bao bì', 'kg', 0.08, 'Vỏ bao PP dệt tải trọng 10 kg dùng đóng gói thức ăn đậm đặc, con giống (vỏ ~0.08 kg/bao)', 'Xếp gọn gàng trên kệ pallet, tránh xa nguồn nhiệt', NULL, 'Đang kinh doanh'),
  ('HH04000011', 'Bao PP dệt 50 kg', 'Bao bì', 'kg', 0.18, 'Vỏ bao PP dệt khổ lớn chịu tải 50 kg đóng gói nguyên liệu thô và cám bò (vỏ ~0.18 kg/bao)', 'Kho khô ráo thoáng mát, chống bụi bẩn', NULL, 'Đang kinh doanh'),
  ('HH04000012', 'Bao BOPP ghép màng', 'Bao bì', 'kg', 0.16, 'Vỏ bao phức hợp ghép màng bóng BOPP chất lượng cao chống thẩm thấu (vỏ ~0.16 kg/bao)', 'Nơi râm mát, tránh ánh nắng chiếu trực tiếp', NULL, 'Đang kinh doanh'),
  ('HH04000013', 'Bao PE lót trong', 'Bao bì', 'kg', 0.09, 'Túi nilon PE lót trong khổ lớn dùng cho bao 40–50 kg ngăn ẩm và chống rò rỉ (vỏ ~0.09 kg/bao)', 'Bọc kín trong túi bảo hộ, tránh bụi bặm', NULL, 'Đang kinh doanh'),
  ('HH04000014', 'Thùng carton 3 lớp', 'Bao bì', 'kg', 0.3, 'Thùng carton sóng 3 lớp trọng lượng nhẹ dùng đóng gói vật tư phụ gia nhỏ (vỏ ~0.30 kg/thùng)', 'Kho khô ráo tuyệt đối, kê cao cách mặt sàn', NULL, 'Đang kinh doanh'),
  ('HH04000015', 'Màng PE quấn pallet', 'Bao bì', 'kg', 3, 'Cuộn màng nhựa căng PE dẻo quấn cố định khối hàng pallet chống ẩm bụi (~3.0 kg/cuộn)', 'Kho râm mát, dựng đứng hoặc xếp ngang giá kệ', NULL, 'Đang kinh doanh'),
  ('HH04000016', 'Bao PP tráng PE', 'Bao bì', 'kg', 0.22, 'Vỏ bao vải PP dệt phủ một lớp tráng keo PE tăng cường chống rách và ẩm (vỏ ~0.22 kg/bao)', 'Nơi khô thoáng, xếp ngay ngắn trên kệ kho', NULL, 'Đang kinh doanh'),
  ('HH04000017', 'Bao giấy nhiều lớp', 'Bao bì', 'kg', 0.35, 'Bao giấy Kraft tự nhiên 3-4 lớp thân thiện môi trường đóng gói premix (vỏ ~0.35 kg/bao)', 'Kho khô ráo tuyệt đối, chống ẩm ướt dột nước', NULL, 'Đang kinh doanh'),
  ('HH04000018', 'Chỉ may bao', 'Bao bì', 'kg', 1, 'Chỉ may công nghiệp dùng đóng miệng bao thức ăn chăn nuôi', 'Nơi khô ráo, sạch sẽ, tránh ẩm và bụi bẩn', NULL, 'Đang kinh doanh'),
  ('HH05000001', 'Premix vitamin heo', 'Phụ gia', 'kg', 25, 'Hỗn hợp vi khoáng và vitamin thiết yếu cho heo các giai đoạn (bao 25 kg)', 'Kho mát < 25°C, tránh ánh sáng trực tiếp, chống ẩm', 180, 'Đang kinh doanh'),
  ('HH05000002', 'Premix vitamin gia cầm', 'Phụ gia', 'kg', 5, 'Hỗn hợp vitamin và khoáng hòa tan chuyên biệt cho gà vịt (thùng 5 kg)', 'Kho lạnh mát 15-22°C, đậy kín sau khi sử dụng', 180, 'Đang kinh doanh'),
  ('HH05000003', 'Premix vitamin thủy sản', 'Phụ gia', 'kg', 25, 'Hỗn hợp vi lượng bền trong nước cho cá tra và tôm (bao 25 kg)', 'Kho mát, đậy kín bao bì tránh hút ẩm', 180, 'Đang kinh doanh'),
  ('HH05000004', 'Lysine', 'Phụ gia', 'kg', 25, 'L-Lysine HCl 98.5% axit amin thiết yếu tổng hợp cân bằng đạm (bao 25 kg)', 'Râm mát, kín khí, tránh không khí ẩm gây vón', 730, 'Đang kinh doanh'),
  ('HH05000005', 'Methionine', 'Phụ gia', 'kg', 25, 'DL-Methionine 99% axit amin gốc lưu huỳnh kích thích tăng trọng (bao 25 kg)', 'Khô ráo, thoáng khí, nhiệt độ phòng tiêu chuẩn', 730, 'Đang kinh doanh'),
  ('HH05000006', 'Enzyme phytase', 'Phụ gia', 'kg', 25, 'Enzyme sinh học giải phóng phospho hữu cơ từ thực vật, tăng hấp thu (bao 25 kg)', 'Kho mát < 25°C, tránh nhiệt cao làm mất hoạt tính men', 365, 'Đang kinh doanh'),
  ('HH05000007', 'Enzyme xylanase', 'Phụ gia', 'kg', 25, 'Enzyme phân giải chất xơ hòa tan giảm độ nhớt đường ruột vật nuôi (bao 25 kg)', 'Kho khô mát, tránh ẩm ướt và ánh nắng trực tiếp', 365, 'Đang kinh doanh'),
  ('HH05000008', 'Probiotic', 'Phụ gia', 'kg', 25, 'Bào tử men vi sinh có ích chịu nhiệt ổn định hệ vi sinh đường ruột (bao 25 kg)', 'Kho mát < 25°C, bao bì ép kín tránh ẩm mốc', 365, 'Đang kinh doanh'),
  ('HH05000009', 'Chất chống oxy hóa', 'Phụ gia', 'kg', 25, 'Hợp chất ngăn ngừa ôi thiu lipid, bảo vệ vitamin và chất béo trong thức ăn (bao 25 kg)', 'Kho khô ráo, thoáng khí, đậy kín sau mở bao', 365, 'Đang kinh doanh'),
  ('HH05000010', 'Threonine', 'Phụ gia', 'kg', 25, 'L-Threonine 98.5% axit amin giới hạn duy trì chức năng niêm mạc ruột (bao 25 kg)', 'Kho râm mát, thông gió tốt, đậy kín miệng bao', 730, 'Đang kinh doanh'),
  ('HH05000011', 'Tryptophan', 'Phụ gia', 'kg', 25, 'L-Tryptophan 98% axit amin thiết yếu kích thích thèm ăn và giảm stress (bao 25 kg)', 'Kho mát mẻ, tránh ánh nắng chiếu trực tiếp', 730, 'Đang kinh doanh'),
  ('HH05000012', 'Choline chloride', 'Phụ gia', 'kg', 25, 'Choline chloride 60% dạng hạt bột hỗ trợ chuyển hóa chất béo tại gan (bao 25 kg)', 'Khô ráo tuyệt đối, chống hút ẩm vón cục', 365, 'Đang kinh doanh'),
  ('HH05000013', 'Vitamin C', 'Phụ gia', 'kg', 25, 'Axit ascorbic dạng bọc chống oxy hóa nâng cao sức đề kháng cho vật nuôi (bao 25 kg)', 'Kho lạnh mát < 20°C, bao bì tráng bạc cản sáng', 365, 'Đang kinh doanh'),
  ('HH05000014', 'Chất hấp phụ độc tố', 'Phụ gia', 'kg', 25, 'Khoáng sét tự nhiên liên kết chọn lọc và đào thải độc tố nấm mốc (bao 25 kg)', 'Kho khô thoáng, kê pallet cách sàn', 730, 'Đang kinh doanh'),
  ('HH05000015', 'Chất chống nấm mốc', 'Phụ gia', 'kg', 25, 'Hợp chất muối propionate ức chế bào tử nấm mốc sinh sôi trong cám (bao 25 kg)', 'Kho khô ráo, đậy kín sau khi sử dụng', 365, 'Đang kinh doanh'),
  ('HH05000016', 'Betaine', 'Phụ gia', 'kg', 25, 'Betaine hydrochloride 98% điều hòa áp suất thẩm thấu và tích lũy nạc (bao 25 kg)', 'Khô mát, chống hút ẩm cực tốt, bao kín', 730, 'Đang kinh doanh'),
  ('HH05000017', 'Axit hữu cơ', 'Phụ gia', 'kg', 25, 'Hỗn hợp axit citric, formic, lactic hạ pH đường tiêu hóa diệt khuẩn hại (bao 25 kg)', 'Nơi râm mát, thông gió tự nhiên, tránh nắng', 365, 'Đang kinh doanh'),
  ('HH05000018', 'Chất tạo màu', 'Phụ gia', 'kg', 25, 'Sắc tố tự nhiên chiết xuất cúc vạn thọ tạo màu vàng lòng đỏ trứng và da gà (bao 25 kg)', 'Kho mát kín gió, giữ trong bao nhôm kín tránh bay màu', 365, 'Đang kinh doanh');
