COMMIT;

-- ---------------------------------------------------------------------
-- [39-40] Pham vi vi tri + so sach dong bang cho cac bien ban kiem ke mau (UC24)
--   Dan xuat tu KetQuaKiemKe da seed de du lieu mau tu nhat quan (bien ban da ghi ket qua
--   thi phai co pham vi vi tri + snapshot tuong ung).
-- ---------------------------------------------------------------------
SELECT q.`maBienBanKiemKe`, q.`maViTri`, 'Đã kiểm tra', MIN(q.`maNhanVienKiemKe`), MIN(b.`ngayBatDau`) + INTERVAL 2 HOUR
FROM `KetQuaKiemKe` q
JOIN `BienBanKiemKe` b ON b.`maBienBanKiemKe` = q.`maBienBanKiemKe`
GROUP BY q.`maBienBanKiemKe`, q.`maViTri`;

SELECT q.`maBienBanKiemKe`, q.`maLoHang`, q.`maViTri`, q.`soLuongSoSach`,
       LEAST(COALESCE((SELECT t.`soLuongDaGiu` FROM `TonKho` t
                       WHERE t.`maLoHang` = q.`maLoHang` AND t.`maViTri` = q.`maViTri`), 0), q.`soLuongSoSach`)
FROM `KetQuaKiemKe` q
WHERE NOT EXISTS (SELECT 1 FROM `SnapshotTonKhoKiemKe` s
                  WHERE s.`maBienBanKiemKe` = q.`maBienBanKiemKe`
                    AND s.`maLoHang` = q.`maLoHang` AND s.`maViTri` = q.`maViTri`);

-- =====================================================================
-- DOI SOAT SAU IMPORT: Chay cac SELECT nay de kiem tra du lieu (READ-ONLY)
-- =====================================================================
SELECT COUNT(*) AS `so_bang_co_du_lieu`
FROM information_schema.tables
WHERE table_schema = DATABASE() AND table_type='BASE TABLE';

-- Bat buoc: 0 dong sai lech ton so cai - TonKho.
SELECT t.maLoHang, t.maViTri, t.soLuongTon,
       COALESCE(b.tongBienDong,0) AS tonTheoSoCai
FROM `TonKho` t
LEFT JOIN (
  SELECT maLoHang, maViTri, SUM(soLuongBienDong) AS tongBienDong
  FROM `LichSuBienDongTonKho` GROUP BY maLoHang,maViTri
) b ON b.maLoHang=t.maLoHang AND b.maViTri=t.maViTri
WHERE ABS(t.soLuongTon-COALESCE(b.tongBienDong,0)) > 0.000001;

-- Bat buoc: 0 dong sai lech giu cho - picking dang giu.
SELECT t.maLoHang, t.maViTri, t.soLuongDaGiu,
       COALESCE(d.tongDangGiu,0) AS giuTheoPicking
FROM `TonKho` t
LEFT JOIN (
  SELECT maLoHang, maViTri, SUM(soLuongDeXuat) AS tongDangGiu
  FROM `DeXuatLoHang` WHERE trangThai='Đã giữ chỗ'
  GROUP BY maLoHang,maViTri
) d ON d.maLoHang=t.maLoHang AND d.maViTri=t.maViTri
WHERE ABS(t.soLuongDaGiu-COALESCE(d.tongDangGiu,0)) > 0.000001;

-- Bat buoc: 0 dong vuot suc chua vi tri.
SELECT v.maViTri, v.tenViTri, v.sucChuaToiDa,
       SUM(t.soLuongTon) AS tongKhoiLuong
FROM `ViTriLuuTru` v JOIN `TonKho` t ON t.maViTri=v.maViTri
GROUP BY v.maViTri,v.tenViTri,v.sucChuaToiDa
HAVING SUM(t.soLuongTon)>v.sucChuaToiDa+0.000001;
